// Cloudflare Pages middleware: a fresh CSP nonce for every HTML response.
//
// Why: the Atlas CSP has no 'unsafe-inline'. Our own inline boot script is allowed by its sha256 hash (dist/_headers,
// generated by atlas/site/build.py). Cloudflare injects one more inline script into every HTML page (JavaScript
// Detections bootstrap for /cdn-cgi/challenge-platform/); its text changes per response, so a hash cannot cover it.
// Cloudflare reads the nonce from our Content-Security-Policy response header and puts it on the scripts it injects
// (https://developers.cloudflare.com/cloudflare-challenges/challenge-types/javascript-detections/#if-you-have-a-content-security-policy-csp).
// We never put this nonce into our own markup: our scripts stay hash-allowed, the nonce exists only for Cloudflare.
//
// Scope: dist/_routes.json limits this Function to HTML pages; assets, JSON and images never invoke it.
// Fail-safe: if the response has no CSP or is not HTML, it is passed through unchanged.
const MARK = "script-src 'self'";

export async function onRequest(context) {
  const res = await context.next();
  const csp = res.headers.get('Content-Security-Policy');
  const type = res.headers.get('Content-Type') || '';
  if (!csp || !type.startsWith('text/html') || !csp.includes(MARK)) return res;
  const bytes = new Uint8Array(18);
  crypto.getRandomValues(bytes);
  const nonce = btoa(String.fromCharCode(...bytes));
  const out = new Response(res.body, res);
  out.headers.set('Content-Security-Policy', csp.replace(MARK, `${MARK} 'nonce-${nonce}'`));
  return out;
}
